#include <algorithm>
#include <cstddef>
#include <functional>
#include <utility>
#include <vector>

template <typename... Args>
class Signal
{
public:
    using Listener = std::function<void(Args...)>;

    int connect(Listener listener)
    {
        m_listeners.emplace_back(m_nextId, std::move(listener));
        return m_nextId++;
    }

    bool disconnect(int id)
    {
        const auto found{ std::find_if(m_listeners.begin(), m_listeners.end(), [id](const auto& entry) { return entry.first == id; }) };
        if (found == m_listeners.end())
        {
            return false;
        }
        m_listeners.erase(found);
        return true;
    }

    void emit(Args... args) const
    {
        const auto snapshot{ m_listeners };
        for (const auto& [id, listener] : snapshot)
        {
            listener(args...);
        }
    }

    std::size_t listenerCount() const { return m_listeners.size(); }

private:
    std::vector<std::pair<int, Listener>> m_listeners{};
    int m_nextId{ 1 };
};

unitTests:
TEST("listeners are called in order with the arguments") { Signal<int, std::string> s{}; std::vector<std::string> log; s.connect([&](int n, std::string t) { log.push_back("a" + std::to_string(n) + t); }); s.connect([&](int n, std::string t) { log.push_back("b" + std::to_string(n) + t); }); s.emit(7, "x"); CHECK_EQ(log, (std::vector<std::string>{ "a7x", "b7x" })); CHECK_EQ(s.listenerCount(), 2u); }
TEST("emitting with nobody listening is fine") { Signal<> s{}; s.emit(); CHECK_EQ(s.listenerCount(), 0u); }
TEST("disconnect") { Signal<int> s{}; int total{ 0 }; const int first{ s.connect([&](int n) { total += n; }) }; const int second{ s.connect([&](int n) { total += 10 * n; }) }; CHECK(first != second); s.emit(1); CHECK_EQ(total, 11); CHECK(s.disconnect(first)); CHECK(!s.disconnect(first)); CHECK(!s.disconnect(9999)); s.emit(1); CHECK_EQ(total, 21); }
TEST("ids are never reused") { Signal<> s{}; const int a{ s.connect([] {}) }; s.disconnect(a); const int b{ s.connect([] {}) }; CHECK(a != b); }
TEST("a listener may disconnect itself during emit") { Signal<> s{}; int calls{ 0 }; int id{ 0 }; id = s.connect([&] { ++calls; s.disconnect(id); }); int others{ 0 }; s.connect([&] { ++others; }); s.emit(); s.emit(); CHECK_EQ(calls, 1); CHECK_EQ(others, 2); CHECK_EQ(s.listenerCount(), 1u); }

